PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS candidates(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL,phone TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,deleted_at TEXT);
CREATE TABLE IF NOT EXISTS positions(id TEXT PRIMARY KEY,title TEXT NOT NULL,department TEXT,status TEXT NOT NULL DEFAULT 'OPEN',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS applications(id TEXT PRIMARY KEY,candidate_id TEXT NOT NULL REFERENCES candidates(id),position_id TEXT REFERENCES positions(id),role TEXT NOT NULL,stage TEXT NOT NULL CHECK(stage IN('DOCUMENT','FIRST_INTERVIEW','FINAL_INTERVIEW','HIRED','REJECTED')),applied_at TEXT NOT NULL,experience TEXT,owner_email TEXT,owner_name TEXT,version INTEGER NOT NULL DEFAULT 1,memo TEXT DEFAULT '',rating REAL DEFAULT 0,resume_key TEXT,resume_name TEXT,updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS applications_stage_idx ON applications(stage,updated_at);
CREATE INDEX IF NOT EXISTS applications_candidate_idx ON applications(candidate_id);
CREATE TABLE IF NOT EXISTS stage_events(id TEXT PRIMARY KEY,application_id TEXT NOT NULL REFERENCES applications(id),from_stage TEXT,to_stage TEXT NOT NULL,actor TEXT NOT NULL,version INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS email_templates(id TEXT PRIMARY KEY,name TEXT NOT NULL,subject TEXT NOT NULL,body_text TEXT NOT NULL,body_html TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,active INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS email_schedules(id TEXT PRIMARY KEY,application_id TEXT NOT NULL REFERENCES applications(id),event_id TEXT NOT NULL,version INTEGER NOT NULL,template_version INTEGER NOT NULL,recipient_email TEXT NOT NULL,scheduled_at TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('PENDING','CANCELLED','PROCESSING','SENT','FAILED','DELIVERED','BOUNCED','UNKNOWN','DELIVERED','BOUNCED','UNKNOWN')),cancelled_at TEXT,claimed_at TEXT,sent_at TEXT,provider_message_id TEXT,retry_count INTEGER NOT NULL DEFAULT 0,last_error TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(event_id));
CREATE INDEX IF NOT EXISTS email_schedules_due_idx ON email_schedules(status,scheduled_at);
CREATE TABLE IF NOT EXISTS audit_logs(id TEXT PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,resource_type TEXT NOT NULL,resource_id TEXT NOT NULL,details TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS evaluations(id TEXT PRIMARY KEY,application_id TEXT NOT NULL REFERENCES applications(id),evaluator_email TEXT NOT NULL,score REAL,notes TEXT,submitted_at TEXT);
CREATE TABLE IF NOT EXISTS interviews(id TEXT PRIMARY KEY,application_id TEXT NOT NULL REFERENCES applications(id),starts_at TEXT NOT NULL,ends_at TEXT,interviewers TEXT NOT NULL,location TEXT,notes TEXT,status TEXT NOT NULL DEFAULT 'SCHEDULED');
INSERT OR IGNORE INTO email_templates(id,name,subject,body_text,body_html,version,active,updated_at) VALUES('rejection-default','불합격 위로 이메일','{{candidate_name}}님, 지원해 주셔서 감사합니다','{{candidate_name}}님께,\n\n이번 채용에 관심을 가지고 지원해 주셔서 진심으로 감사드립니다. 아쉽게도 이번에는 함께하기 어렵게 되었습니다. 지원 과정에서 보여주신 시간과 노고에 감사드리며, 앞으로의 여정에 좋은 일이 가득하기를 바랍니다.\n\n감사합니다.\n채용팀','<p>{{candidate_name}}님께,</p><p>이번 채용에 관심을 가지고 지원해 주셔서 진심으로 감사드립니다. 아쉽게도 이번에는 함께하기 어렵게 되었습니다. 지원 과정에서 보여주신 시간과 노고에 감사드리며, 앞으로의 여정에 좋은 일이 가득하기를 바랍니다.</p><p>감사합니다.<br>채용팀</p>',1,1,datetime('now'));
